  "test_path": "tests/test_integer_parameter_type.py",
  "test": "import pytest
from pydantic import ValidationError

from browser_use.skills.utils import convert_parameters_to_pydantic

class DummyParam:
    def __init__(self, name, type, required=True, description=None):
        self.name = name
        self.type = type
        self.required = required
        self.description = description

def test_integer_parameter_maps_to_int():
    params = [DummyParam(name='age', type='integer', required=True)]
    Model = convert_parameters_to_pydantic(params, model_name='TestModel')
    # Valid integer should pass validation
    instance = Model(age=42)
    assert instance.age == 42
    # Non‑integer should raise a validation error
    with pytest.raises(ValidationError):
        Model(age='not-an-int')
"
